}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; display: block; }

h1, h2, h3 { font-weight: 600; line-height: 1.15; letter-spacing: -0.01em; margin: 0; }
h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 2.6vw, 2.125rem); }
h3 { font-size: 1.125rem; }
p  { margin: 0; color: var(--ink-soft); }

a { color: inherit; text-decoration: none; }
a:hover { text-decoration: underline; text-underline-offset: 3px; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.container {
  width: 100%;
  max-width: var(--container);
  margin-inline: auto;
  padding-inline: clamp(1rem, 3vw, 2rem);
}

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem; top: -100px;
  background: var(--ink);
  color: var(--accent-contrast);
  padding: .65rem 1rem;
  border-radius: 8px;
  z-index: 100;
  font-weight: 600;
}
.skip-link:focus { top: 1rem; }

/* HEADER */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250, 250, 247, 0.85);
  backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  min-height: 72px;
}
.brand {
  display: inline-flex; align-items: center; gap: .5rem;
  font-weight: 700; letter-spacing: .02em;
  font-size: 1.05rem;
}
.brand:hover { text-decoration: none; }
.brand-mark {
  display: inline-grid; place-items: center;
  width: 28px; height: 28px;
  background: var(--ink); color: var(--accent-contrast);
  border-radius: 6px; font-size: .8rem;
}
.primary-nav ul {
  display: flex; gap: 1.75rem;
  list-style: none; margin: 0; padding: 0;
  justify-content: center;
}
.primary-nav a {
  font-size: .94rem; font-weight: 500; color: var(--ink-soft);
  padding: .35rem 0; position: relative;
}
.primary-nav a:hover { color: var(--ink); text-decoration: none; }
.primary-nav a::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -2px;
  height: 2px; background: var(--ink);
  transform: scaleX(0); transform-origin: left;
  transition: transform .2s ease;
}
.primary-nav a:hover::after,
.primary-nav a:focus-visible::after { transform: scaleX(1); }

.header-actions {
  display: flex; align-items: center; gap: .5rem;
}
.search {
  display: flex; align-items: center;
  background: var(--muted);
  border-radius: 999px;
  padding: .35rem .35rem .35rem 1rem;
  border: 1px solid transparent;
  transition: border-color .15s ease, background .15s ease;
}
.search:focus-within { border-color: var(--ink); background: var(--surface); }
.search input {
  border: 0; background: transparent; outline: none;
  font: inherit; min-width: 200px;
}
.search button {
  border: 0; background: var(--ink); color: var(--accent-contrast);
  width: 34px; height: 34px; border-radius: 999px;
  display: grid; place-items: center; cursor: pointer;
}
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  border-radius: 999px;
  border: 1px solid transparent;
  background: transparent; cursor: pointer;
  display: grid; place-items: center;
  color: var(--ink);
}
.icon-btn:hover { background: var(--muted); }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  min-width: 18px; height: 18px; padding: 0 5px;
  background: var(--brand); color: #fff;
  border-radius: 999px; font-size: .7rem; font-weight: 700;
  display: grid; place-items: center; line-height: 1;
}

/* HERO */
.hero { padding: clamp(2.5rem, 6vw, 5rem) 0 clamp(2rem, 5vw, 4rem); }
.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}
.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .78rem;
  font-weight: 600;
  color: var(--brand);
  margin-bottom: .75rem;
}
.lede { font-size: 1.15rem; max-width: 52ch; margin-top: 1.25rem; }
.hero-actions { display: flex; gap: .75rem; margin-top: 2rem; flex-wrap: wrap; }

.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: .85rem 1.4rem;
  border-radius: 999px;
  font-weight: 600; font-size: .95rem;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform .12s ease, background .15s ease, color .15s ease, border-color .15s ease;
}
.btn:hover { text-decoration: none; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn-primary { background: var(--ink); color: var(--accent-contrast); }
.btn-primary:hover { background: #2c2c28; }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn-ghost:hover { background: var(--ink); color: var(--accent-contrast); }

.hero-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
  margin: 2.5rem 0 0;
  padding-top: 2rem;
  border-top: 1px solid var(--line);
}
.hero-stats div { display: flex; flex-direction: column; gap: .15rem; }
.hero-stats dt { font-weight: 600; font-size: .92rem; }
.hero-stats dd { margin: 0; color: var(--ink-faint); font-size: .85rem; }

.hero-art {
  position: relative;
  margin: 0;
  aspect-ratio: 4 / 5;
  background: linear-gradient(160deg, #ece6dc 0%, #d9cfbf 100%);
  border-radius: 24px;
  overflow: hidden;
  box-shadow: var(--shadow-md);
}
.hero-art-shape { position: absolute; border-radius: 50%; }
.shape-a { width: 60%; aspect-ratio: 1; left: -10%; top: -10%; background: radial-gradient(circle at 30% 30%, #c98c6e, #b8553a); opacity: .9; }
.shape-b { width: 45%; aspect-ratio: 1; right: -8%; bottom: 8%; background: radial-gradient(circle at 70% 70%, #f3e1d2, #d9bfa6); }
.shape-c { width: 30%; aspect-ratio: 1; left: 22%; bottom: -10%; background: #1a1a18; opacity: .85; }
.hero-art-card {
  position: absolute; left: 1.25rem; bottom: 1.25rem;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(8px);
  padding: .85rem 1rem;
  border-radius: 12px;
  display: grid; gap: .15rem;
  font-size: .85rem;
  box-shadow: var(--shadow-sm);
}
.hero-art-tag { color: var(--brand); font-weight: 600; font-size: .7rem; text-transform: uppercase; letter-spacing: .12em; }
.hero-art-name { font-weight: 600; }
.hero-art-price { color: var(--ink-faint); }

/* CATEGORIES */
.categories { padding: 1rem 0 2.5rem; }
.category-list {
  list-style: none; margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: .75rem;
}
.category-list a {
  display: flex; align-items: center; gap: .65rem;
  background: var(--surface);
  border: 1px solid var(--line);
  padding: .9rem 1rem;
  border-radius: var(--radius);
  font-weight: 500; font-size: .95rem;
  transition: border-color .15s ease, transform .15s ease, box-shadow .15s ease;
}
.category-list a:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
  text-decoration: none;
}
.cat-icon {
  width: 28px; height: 28px;
  display: grid; place-items: center;
  background: var(--muted); border-radius: 8px;
  font-size: .9rem;
}

/* SECTIONS */
.section { padding: clamp(3rem, 6vw, 5rem) 0; }
.section-muted { background: var(--muted); }
.section-head {
  display: flex; align-items: end; justify-content: space-between;
  gap: 1.5rem; margin-bottom: 2rem; flex-wrap: wrap;
}
.section-head .eyebrow { margin-bottom: .5rem; }
.section-sub { margin-top: .5rem; max-width: 50ch; }
.link-arrow {
  font-weight: 600; font-size: .95rem;
  display: inline-flex; align-items: center; gap: .35rem;
  border-bottom: 1px solid currentColor;
  padding-bottom: 2px;
}
.link-arrow:hover { text-decoration: none; color: var(--brand); }

/* PRODUCT GRID */
.product-grid {
  list-style: none; margin: 0; padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}
.product {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.product:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-color: transparent;
}
.product-media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--muted);
  overflow: hidden;
}
.product-media-art {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  font-size: 3rem; color: rgba(0,0,0,.18);
}
.product-badge {
  position: absolute; top: .75rem; left: .75rem;
  background: var(--ink); color: var(--accent-contrast);
  font-size: .7rem; font-weight: 600;
  padding: .25rem .55rem; border-radius: 999px;
  text-transform: uppercase; letter-spacing: .08em;
}
.product-badge.sale { background: var(--brand); }
.product-badge.new { background: var(--success); }
.product-fav {
  position: absolute; top: .6rem; right: .6rem;
  width: 36px; height: 36px; border-radius: 999px;
  background: rgba(255,255,255,.92);
  border: 0; cursor: pointer;
  display: grid; place-items: center;
  color: var(--ink); transition: transform .15s ease, background .15s ease;
}
.product-fav:hover { transform: scale(1.05); }
.product-fav[aria-pressed="true"] { color: var(--brand); }
.product-fav[aria-pressed="true"] svg path { fill: currentColor; }
.product-body { padding: 1rem 1rem 1.1rem; display: grid; gap: .35rem; }
.product-cat { font-size: .78rem; color: var(--ink-faint); text-transform: uppercase; letter-spacing: .1em; }
.product-name { font-size: 1rem; font-weight: 600; }
.product-row { display: flex; align-items: center; justify-content: space-between; margin-top: .25rem; gap: .75rem; }
.product-price { font-weight: 600; }
.product-price .price-was { color: var(--ink-faint); font-weight: 400; margin-left: .35rem; font-size: .9em; }
.product-rating { display: inline-flex; align-items: center; gap: .25rem; font-size: .82rem; color: var(--ink-faint); }
.product-rating::before { content: "★"; color: #d4a017; }
.product-add {
  margin: 0 1rem 1rem; padding: .65rem 1rem;
  background: var(--muted); color: var(--ink);
  border: 1px solid transparent;
  border-radius: 999px; font-weight: 600; font-size: .88rem;
  cursor: pointer;
  transition: background .15s ease, color .15s ease;
}
.product-add:hover { background: var(--ink); color: var(--accent-contrast); }

/* DEALS */
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 1.25rem;
}
.deal {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  display: grid; grid-template-rows: minmax(160px, 1fr) auto;
  border: 1px solid var(--line);
  transition: transform .18s ease, box-shadow .18s ease;
}
.deal:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.deal-large { grid-row: span 2; grid-template-rows: 1fr auto; }
.deal-art { background: var(--muted); }
.deal-art-1 { background: linear-gradient(135deg, #d6b59e 0%, #b8553a 100%); min-height: 280px; }
.deal-art-2 { background: linear-gradient(135deg, #e2dccf 0%, #a89e84 100%); }
.deal-art-3 { background: linear-gradient(135deg, #cfd9d2 0%, #6f8a7a 100%); }
.deal-body { padding: 1.25rem; display: grid; gap: .5rem; align-content: start; }
.deal-large .deal-body { padding: 1.5rem; gap: .65rem; }
.deal-tag { display: inline-block; align-self: start; background: var(--ink); color: var(--accent-contrast); padding: .25rem .6rem; border-radius: 999px; font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; }
.deal-price { display: flex; align-items: baseline; gap: .5rem; font-weight: 600; font-size: 1.05rem; }
.price-was { color: var(--ink-faint); font-weight: 400; font-size: .9em; }
.price-now { color: var(--ink); }
.deal h3 { font-size: 1.15rem; }
.deal-large h3 { font-size: 1.5rem; }

.countdown {
  display: inline-flex; flex-direction: column; align-items: end;
  gap: .15rem;
  padding: .6rem .9rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
}
.countdown-label { font-size: .72rem; color: var(--ink-faint); text-transform: uppercase; letter-spacing: .12em; }
.countdown-time { font-variant-numeric: tabular-nums; font-weight: 700; font-size: 1.05rem; }

/* EDITORIAL */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}
.editorial-card {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--line);
  transition: transform .18s ease, box-shadow .18s ease;
}
.editorial-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.editorial-feature { grid-row: span 2; }
.editorial-link { display: block; height: 100%; color: inherit; }
.editorial-link:hover { text-decoration: none; }
.editorial-art { aspect-ratio: 16/10; background: var(--muted); }
.editorial-feature .editorial-art { aspect-ratio: 4/3; }
.editorial-art-1 { background: linear-gradient(140deg, #ead7c5 0%, #b8553a 100%); }
.editorial-art-2 { background: linear-gradient(140deg, #d6dcd2 0%, #4a5b54 100%); }
.editorial-art-3 { background: linear-gradient(140deg, #efe7d8 0%, #8a7a5e 100%); }
.editorial-body { padding: 1.25rem; display: grid; gap: .6rem; }
.editorial-feature .editorial-body { padding: 1.5rem; gap: .85rem; }
.editorial-card h3 { font-size: 1.05rem; line-height: 1.3; }
.editorial-feature h3 { font-size: 1.5rem; }
.byline { display: inline-flex; align-items: center; gap: .55rem; font-size: .85rem; color: var(--ink-faint); }
.avatar {
  width: 28px; height: 28px; border-radius: 50%;
  background: var(--brand-soft); color: var(--brand);
  display: grid; place-items: center;
  font-size: .72rem; font-weight: 700;
}

/* NEWSLETTER */
.newsletter {
  background: var(--ink); color: var(--accent-contrast);
  padding: clamp(2.5rem, 5vw, 4rem) 0;
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 2rem;
}
.newsletter h2 { color: var(--accent-contrast); }
.newsletter p { color: rgba(255,255,255,.75); margin-top: .5rem; }
.newsletter-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .5rem;
  position: relative;
}
.newsletter-form input {
  padding: .9rem 1.1rem;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.08);
  color: #fff; font: inherit;
}
.newsletter-form input::placeholder { color: rgba(255,255,255,.55); }
.newsletter-form input:focus { outline-color: #fff; background: rgba(255,255,255,.14); }
.newsletter-form .btn-primary { background: #fff; color: var(--ink); }
.newsletter-form .btn-primary:hover { background: #f1ddd2; }
.form-status { grid-column: 1 / -1; margin-top: .25rem; min-height: 1.2em; font-size: .9rem; color: rgba(255,255,255,.85); }
.form-status.error { color: #ffb3a3; }
.form-status.success { color: #b8f3c8; }

/* FOOTER */
.site-footer { background: var(--bg); border-top: 1px solid var(--line); padding: 3rem 0 1.25rem; }
.footer-inner {
  display: grid;
  grid-template-columns: 1.2fr 2fr;
  gap: 2rem;
  align-items: start;
}
.footer-brand { display: grid; gap: .5rem; align-content: start; }
.footer-brand .brand-mark { width: 32px; height: 32px; }
.footer-brand p { color: var(--ink-faint); }
.site-footer nav { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.footer-col h3 { font-size: .85rem; text-transform: uppercase; letter-spacing: .12em; margin-bottom: .9rem; }
.footer-col ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .55rem; }
.footer-col a { color: var(--ink-soft); font-size: .92rem; }
.footer-col a:hover { color: var(--ink); }
.footer-base {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: 2.5rem; padding-top: 1.25rem;
  border-top: 1px solid var(--line);
  color: var(--ink-faint); flex-wrap: wrap; gap: 1rem;
}
.legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 1.25rem; font-size: .85rem; }

/* TOAST */
.toast {
  position: fixed; left: 50%; bottom: 1.5rem;
  transform: translate(-50%, 120%);
  background: var(--ink); color: var(--accent-contrast);
  padding: .75rem 1.1rem; border-radius: 999px;
  box-shadow: var(--shadow-md);
  font-size: .92rem; font-weight: 500;
  pointer-events: none;
  transition: transform .25s ease;
  z-index: 80;
}
.toast.show { transform: translate(-50%, 0); }

/* RESPONSIVE */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-list { grid-template-columns: repeat(3, 1fr); }
  .deals-grid {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto auto;
  }
  .deal-large { grid-column: 1 / -1; grid-row: auto; grid-template-rows: 200px auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-feature { grid-row: auto; }
}

@media (max-width: 760px) {
  .header-inner { grid-template-columns: auto auto; gap: .75rem; }
  .primary-nav { grid-column: 1 / -1; order: 3; overflow-x: auto; }
  .primary-nav ul { justify-content: flex-start; gap: 1.25rem; padding-bottom: .25rem; }
  .search { display: none; }
  .hero-inner { grid-template-columns: 1fr; }
  .hero-art { aspect-ratio: 5/4; order: -1; }
  .hero-stats { grid-template-columns: 1fr; gap: .75rem; padding-top: 1.25rem; margin-top: 1.5rem; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-large { grid-template-rows: 220px auto; }
  .newsletter-inner { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
  .site-footer nav { grid-template-columns: repeat(3, 1fr); gap: 1rem; }
  .section-head { align-items: start; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; scroll-behavior: auto !important; }
}

